"1j3":"Megagalpão no Subúrbio",
"1j4":"O Mais Barato",
"1j5":"O Outro Prédio",
"1j6":"Um grande provedor errou na digitação e anunciou seus prefixos por 18 minutos. O pedido de desculpas demorou mais. Muitas redes ainda estão mandando seu tráfego para o vazio.",
"1j7":"Uma cidade futurista que ainda não foi construída, demo day em {city}",
"1j8":"<b>Um gigaprojeto quer uma demo.</b><br>{bw} por quatro dias em {city}, para exibir uma cidade que ainda é quase só renderização. Veja a aba Negócios.",
"1j9":"<b>Cabo do Báltico danificado</b><br>Um navio cargueiro arrastou a âncora por 100 km. Você não tem links nesses cabos.",
"1ja":"<b>Cabo danificado no Báltico</b><br>Seus links fora do ar: {n}, por cerca de {d} dias.",
"1jb":"<b>BGP hijack</b><br>Outra rede está anunciando seus prefixos. O alcance fica baixo até limparem a bagunça.",
"1jc":"<b>Cabos cortados no Mar Vermelho</b><br>Um navio arrastou a âncora por vários cabos. Todo mundo culpa todo mundo. Por sorte você não usa esses cabos.",
"1jd":"<b>Cabos cortados no Mar Vermelho</b><br>Seus links submarinos fora do ar: {n}, por cerca de {d} dias, enquanto os diplomatas discutem sobre os navios de reparo.",
"1je":"Ligue para todo mundo que você conhece",
"1jf":"Cogentle e Goggle estão brigando por peering. A Goggle está inacessível pelo transit da Cogentle.",
"1jg":"<b>A Drizzle Electric te mandou um bolo IPv6.</b><br>Você vendeu por $8k.",
"1jh":"Escalar para o CTO deles",
"1ji":"O Faceplant cansou das taxas de uso coreanas e mudou em silêncio os usuários coreanos para os servidores de Hong Kong. As páginas se arrastam para todo mundo em Seoul. O regulador está preparando uma multa.",
"1jj":"<b>O Faceplant rerroteou a Coreia via Hong Kong.</b><br>Os usuários de Seoul recebem um quinto a menos dele por 20 dias, não importa como você se conecte.",
"1jk":"<b>A Glitch está saindo da Coreia.</b><br>O site de streaming de games diz que as taxas de rede coreanas são “proibitivamente caras” e fecha as portas lá. O tráfego de Seoul dela cai pela metade, para sempre. Os streamers locais já mudaram de casa.",
"1jl":"<b>Golden Week!</b><br>A demanda na China continental sobe 40% por uma semana.",
"1jm":"<b>Disputa de licença de ancoragem em {city}</b><br>Dois ministérios reivindicam a mesma praia. Nenhum novo link submarino pode chegar ali por 45 dias.",
"1jn":"<b>{name} atinge {city}</b><br>Faltou energia e seu POP fica apagado por dois dias. Um gerador teria salvado.",
"1jo":"<b>{name} atinge {city}</b><br>A rede elétrica caiu, mas seu gerador de backup manteve os routers ligados.",
"1jp":"{name} derrubou a energia em {city}. Seu POP não tem gerador.",
"1jq":"<b>Saiu a nova temporada de “Stranger Pings”!</b><br>A demanda de eyeballs sobe 25% por uma semana. Tem folga?",
"1jr":"<b>Derretimento do control plane óptico!</b><br>Todas as waves alugadas em {reg} apagaram de uma vez. Sua dark fiber própria está ok. É por isso que as pessoas têm fibra própria.",
"1js":"<b>Offline por decreto em {city}</b><br>Um shutdown do governo em dia de prova. Seu POP lá fica apagado por um dia.",
"1jt":"<b>Briga de peering!</b><br>A Cogentle cortou o peering com a Goggle por 20 dias. O tráfego da Goggle via transit Cogentle sumiu. Faça peering direto com a Goggle ou use outro upstream.",
"1ju":"As autoridades mandaram todas as redes em {city} desligarem por um dia durante os exames nacionais. Sim, isso acontece de verdade.",
"1jv":"<b>Verba para banda larga rural: +$30k</b><br>O Ministério dos Tubos gosta do que você está fazendo.",
"1jw":"<b>Sanções!</b><br>A República da Papelada sancionou o fornecedor de parafusos favorito do fabricante dos seus roteadores. As peças estão lentas: por 60 dias, quedas de roteador levam o dobro do tempo para consertar.",
"1jx":"<b>Treino de internet soberana</b><br>Moscou se desconectou do resto da internet por um dia só para ver o que acontece. Tudo que sai da Rússia fica no escuro até amanhã.",
"1jy":"<b>A fronteira ficou mais rígida.</b><br>O packet loss transfronteiriço sobe para 35% por 10 dias. Rotas premium quase não são afetadas.",
"1jz":"<b>Os vizinhos brigaram.</b><br>Uma crise diplomática fecha fronteiras e espaço aéreo em volta do Catar. Todos os links entre Doha e Arábia Saudita ou Emirados ficam fora por cerca de {n} dias. Dê a volta longa, por mar.",
"1k":"Lançar um tubo até",
"1k0":"<b>Guerra comercial das ópticas</b><br>Dois governos taxaram os lasers um do outro. Ópticas custam 40% a mais por 90 dias.",
"1k1":"<b>Os preços de transit caíram 8%.</b><br>Isso acontece todo ano. Ninguém sabe onde fica o fundo do poço.",
"1k2":"Tufão Packet-Loss",
"1k3":"Seu fornecedor de waves empurrou uma atualização malformada para o control plane óptico, e ela inundou todos os nós. Todas as {n} waves alugadas que você tem em {reg} apagaram. A página de status deles diz “degradado”.",
