"1zy":"Dark fiber atravessando a fronteira chinesa não está à venda. Compre uma wave transfronteiriça.",
"1zz":"Dark fiber desbloqueia no nível de clientes 2. Você precisa de escala para justificar comprar seu próprio equipamento óptico.",
"2":"Acender par {n} <small>{price}</small>",
