"2ma":"Celulares em cada ilha de Papua-Nova Guiné a Tonga, e transit para vender em cada uma.",
"2mb":"Movido a roedores renováveis. O uptime depende do horário do lanche.",
"2mc":"O ISP empresarial de Porto Rico, rodando e rodando em volta do IX da ilha.",
"2md":"A desafiante da fibra em Reunião, empolgadíssima com tudo, principalmente com peering.",
"2me":"Racks na nave, refrigeração na cripta. Uptime divino.",
"2mf":"Cuida do correio, dos telefones e da internet na Nova Caledônia e na Polinésia Francesa. Os pacotes chegam selados, com um croissant.",
"2mg":"Cuida da rede da vila entre um chamado e outro.",
"2mh":"Banda larga rural para as ilhas, uma oliveira de cada vez.",
"2mi":"Fibra rural que segue as rotas dos tratores.",
"2mj":"A banda larga de Samoa, prometida com uma fatia de algo doce.",
"2mk":"A telefônica de Saskatchewan, ainda da província e ainda contando histórias sobre os Roughriders.",
"2ml":"Servidores resfriados pelo lago, depois usados para aquecer a sauna.",
"2mm":"Lento na subida, rápido no plano.",
"2mn":"Preços apimentados, latência suave.",
"2mo":"Nasceu em Veneza. Depois foi promovido a terra firme.",
"2mp":"Doce, aveludado e surpreendentemente confiável.",
"2mq":"Dez mil GPUs e um podcast.",
"2mr":"A incumbente da ilha e sócia na maioria dos seus cabos. Ainda não foi extinta.",
"2ms":"A operadora da própria ilha, da mesma cor do licor.",
"2mt":"A operadora das Maldivas, em ilhas a um metro acima do mar, com cabos até o Sri Lanka e a Índia.",
"2mu":"A operadora das Ilhas Marshall, a dois metros acima do mar e orgulhosa de cada centímetro.",
"2mv":"O único carrier do norte: fibra pelas estradas até Whitehorse e Yellowknife, satélites para tudo o que fica além.",
"2mw":"O plus é uma taxa de uso. Peering pago, por gigabit.",
"2mx":"A mesma operadora do Pacífico, um oceano para o lado: um chip em cada ilha, da Jamaica a Trinidad.",
"2my":"A velha operadora das Seychelles, aberta a peering, mas sem nenhum lugar local para fazer isso.",
"2mz":"A incumbente das Ilhas Salomão, num cabo que finalmente chegou em 2020.",
"2n":"Pular",
"2n0":"A operadora de Santa Helena, Ascensão e das Malvinas. O link está no ar? Quase certeza.",
"2n1":"A incumbente do Reino Unido. Zumbe educada, ferroa no preço.",
"2n2":"Encorpado, reconfortante e muito New England.",
"2n3":"Filmes de três horas, zero segundo pra começar.",
"2n4":"Três servidores, um desumidificador e uma avó muito paciente.",
"2n5":"A tele própria de Tonga. Sobreviveu a um vulcão que cortou seu único cabo, e agora mantém um satélite de reserva.",
"2n6":"Levou um gigante do streaming aos tribunais para decidir quem paga pelo tráfego que os próprios clientes pediram. Peering pago, por gigabit.",
"2n7":"A incumbente de Trinidad e Tobago. Seu pedido de peering está na fila, atrás do Carnaval.",
"2n8":"O molhinho especial dos ISPs de Utah.",
"2n9":"Chat de voz para milhões de gamers que falam todos ao mesmo tempo.",
"2na":"Voluntários com antenas no telhado e opiniões fortes sobre IPv6.",
"2nb":"Wi-Fi em toda balsa, backhaul em toda ponte.",
"2nc":"Wi-Fi nos micro-ônibus, e a música é de graça.",
"2nd":"Internet wireless do alto de um silo de grãos.",
"2ne":"Links wireless pela tundra. De vez em quando tem uns chifres no caminho.",
"2nf":"Yee-haw e órbita baixa da Terra.",
"2ng":"<b>A Austrália ficou mais australiana.</b><br>O trânsito lá agora custa três vezes o preço normal, só as operadoras que realmente vendem trânsito na Austrália o vendem, e Telstraya e Floptus só fazem peering privado, então as sessões delas no IX terminaram. Confira seus POPs australianos.",
"2nh":"<b>Novas redes no mapa.</b><br>Esta atualização adicionou redes às quais você ainda não está conectado. Por {n} dias uma rota de cortesia gratuita as alcança, para seu alcance não despencar da noite pro dia. Faça peering com elas, ou compre transit, antes que acabe.",
"2ni":"<b>Algo no NOC deu pau.</b><br>O jogo continuou. Se algo parecer estranho, exporte seu save e abra uma issue no GitHub.",
"2nj":"<b>Bem-vindo de volta, {name}.</b><br>Sua rede está do jeitinho que você deixou: {date}.",
"2nk":"<b>Não deu para carregar seu jogo salvo.</b><br>Ele estava corrompido, então guardamos um backup e você pode começar do zero.",
