"2ru":"Achou um bug ou teve uma ideia?",
"2rv":"How the Internet Works",
"2rw":"Entre no chat do NOC",
"2rx":"Abrir →",
"2ry":"Nosso grupo no Signal: troque capturas de tela e discuta política de peering com outros jogadores. Menos retroescavadeiras que na vida real.",
"2rz":"Conte para a gente no GitHub: um formulário curto para bugs, ideias de recursos, balanceamento e traduções. Lemos todos.",
"2s":"Lento demais: ache um caminho mais rápido.",
"2s0":"A coisa de verdade, por Thomas Kjær Aabo: um mapa interativo com zoom de como seus pacotes viajam de fato, do Wi-Fi à fibra submarina, hoje, em 2010 e em 1995. Este jogo inventa tudo pelo caminho. Aquele acerta.",
"2s1":"A coisa de verdade: siga um pacote do Wi-Fi até a fibra submarina.",
"2s2":"Lançar seu próprio cabo submarino…",
"2s3":"Seu próprio cabo submarino <small>nível {n} ou Tier 1</small>",
"2s4":"As classificações ordenam o tráfego com outros jogadores, o tráfego total, os POPs, as tartes no céu e o cone de clientes das últimas 24 horas, em total ou crescimento. Nunca dinheiro. O teu servidor calcula-as e o teu jogo confere uma linha de vez em quando. Humanos e IA juntos ou à parte, com filtros por região, mercado de origem, idade da rede e mais.",
"2s5":"Acordos",
"2s6":"Cada acordo vai selado para os dois jogadores. Os servidores levam-no mas não o podem ler: nem a oferta, nem o preço, nem porque alguém disse não. Só os projetos de consórcio abertos a todos são públicos.",
"2s7":"Nos primeiros 30 dias, os novatos compram a redes estabelecidas com 25% de desconto. Uma rede estabelecida que faz negócio com um novato ganha um bónus de mentor único quando o novato cresce: 10 POPs, Tier 2 ou um cliente de trânsito próprio.",
"2s8":"Como funciona o Multimode",
"2s9":"Entrar",
"2sa":"O Multimode traz as redes de outras pessoas para o teu jogo. Cada um continua a jogar o seu próprio jogo no seu próprio aparelho: os servidores só passam notas assinadas entre jogos. É por jogo guardado e totalmente opcional.",
"2sb":"Silencia uma rede e ela desaparece do teu jogo, só para ti. Denuncia uma e os operadores do teu servidor vão ver. Os operadores podem esconder uma rede no seu servidor, e quando servidores suficientes votam para a excluir, fica excluída em todo o lado. Os votos não são públicos: só vês quem está excluído e, se fores tu, os motivos. O teu jogo continua sempre.",
"2sc":"Silenciar, denunciar e excluir",
"2sd":"Novatos e mentores",
"2se":"Nada se parte. O teu jogo continua, o que fazes espera numa fila e sai depois, e os acordos em curso mantêm-se. Uma rede que fica calada desvanece devagar: ao fim de uma semana o tráfego passa para outras rotas, ao fim de umas cinco semanas os acordos terminam com um aviso. Nunca uma fatura surpresa.",
"2sf":"As redes de outros jogadores são sítios que os teus clientes querem alcançar. Faz peering com elas, também nos exchanges onde estão listadas, compra-lhes trânsito, PNIs, portas de exchange e waves, troca capacidade ou construam juntos um cabo em consórcio. Cada rede publica a sua política e os seus preços, e os pedidos que os cumprem podem ser aceites sozinhos, mesmo com o outro jogador ausente. O dinheiro nunca passa de um jogo guardado para outro: cada jogo regista o seu lado.",
"2sg":"Os acordos são privados",
"2sh":"Servidores e operadores",
"2si":"Os servidores são geridos por jogadores, cada um por um ou mais operadores, e qualquer pessoa pode ter um. Alguns sincronizam com outros servidores, para conheceres jogadores além do teu. O looking glass mostra cada servidor que o teu jogo conhece e como sincroniza. Podes entrar em até quatro.",
"2sj":"Liga <b>Jogar com outros</b> ao começar um jogo novo no ecrã inicial, ou entra mais tarde em Multimode no menu ou nas Configurações. Puzzles, cenários, Sandbox e Open gates continuam a ser só para um jogador. O nome da tua rede é público em cada servidor em que entras, por isso é melhor não usares o teu nome verdadeiro.",
"2sk":"Quando um servidor cai",
"2sl":"A identidade Multimode da tua rede é uma chave privada guardada neste jogo. <b>Mudar para outro aparelho</b>, na folha de Multimode, descarrega o único ficheiro que a leva. Quem tiver esse ficheiro pode falar como a tua rede, por isso nunca o partilhes nem o anexes a um relatório de erro. As exportações e os jogos partilhados nunca levam a chave.",
