"2te":"Também tens um POP aqui",
"2tf":"Não tens POP aqui",
"2tg":"Uma rede móvel com nome de brinde. Tim-tim para cada torre 5G.",
"2th":"Uma operadora espanhola estrelando em todo mercado latino-americano, pelo menos até vender o próximo.",
"2ti":"Uma operadora minúscula num país onde os cabos do mundo chegam à terra. Os preços acompanham.",
"2tj":"A gigante móvel da África, num amarelo que dá para ver do espaço. Nunca está vazia de verdade.",
"2tk":"Um edge cloud que, apesar do nome, é bem rápido.",
"2tl":"O grandão da Austrália. G'day, são nove dólares o megabit. Ops, gigabit.",
"2tm":"O número dois da Austrália. Uma vez deixou o país inteiro offline por doze horas com uma atualização de rotina.",
"2tn":"Fibra na Bay Area com uma atitude à moda antiga: peering aberto e um ser humano de verdade no telefone.",
"2to":"Coloca o outback online a 550 km de altura e depois aterrissa tudo num data center em Sydney, como todo mundo.",
"2tp":"Comprada pela Speedyloop, e ainda tentando decidir qual nome vai na fatura.",
"2tq":"O gigante mobile do Brasil. Vivíssimo.",
"2tr":"Une Europa e Ásia, e de vez em quando a sua tabela BGP.",
"2ts":"Banda larga a cabo em toda a Europa Central. Até mais, na fila do suporte.",
"2tt":"Banda larga a cabo para meia América. Assombra seus traceroutes.",
"2tu":"Banda larga a cabo para o Sun Belt. Comprada pela Spectre-um, ainda estão vendo de quem é o logo que vai na van.",
"2tv":"Cabos pelo Caribe inteiro, servidos com muita espuma.",
"2tw":"Tá me ouvindo agora? Só se pagar pela PNI.",
"2tx":"O gigante canadense do cabo, preso com fita adesiva. De vez em quando cai tudo de uma vez, o que pelo menos é coerente.",
"2ty":"Fibra do Cabo ao Cairo atravessando uma dúzia de fronteiras. Às vezes por terra, às vezes acima do orçamento.",
"2tz":"Cobra caro. Só peering pago, e o nome já diz tudo.",
"2u":"Tentar de novo",
"2u0":"Chat, jogos e pagamentos. Cada mensagem custa dez centavos.",
"2u1":"Banda larga barata, com o discurso de vendas em loop eterno.",
"2u2":"O transit mais barato do mapa. Famoso pela gentileza, menos durante as brigas de peering.",
