"3j9":"Este POP: {kind}",
"3ja":"Padrões de POP",
"3jb":"40% de desconto por 6 meses",
"3jc":"<b>40% de desconto no {ix} por 6 meses.</b><br>Seu account manager respirou aliviado. Leia as letras miúdas depois.",
"3jd":"<b>“Depois de consultar a diretoria…”</b><br>O preço subiu. A diretoria foi consultada.",
"3je":"Depois disso, volta o preço normal, mais uma pequena taxa de administração de fidelidade.",
"3jf":"<b>Ampliação encomendada com {net}.</b><br>{eta}.",
"3jg":"<b>A ampliação com {net} está ativa:</b> {port}.",
"3jh":"DE-KICKS Group · Customer Success",
"3ji":"<b>O comercial da DE-KICKS ainda está “se alinhando”.</b><br>Eles retornam em {n} dias.",
"3jj":"<b>A DE-KICKS vai “dar um retorno”.</b><br>Espere um e-mail com o assunto “Pergunta rápida 🙂” dentro de uma hora.",
"3jk":"<b>Negociação pausada.</b><br>{why}",
"3jl":"<b>“Só desta vez.”</b><br>Seu account manager achou um desconto especial. Não conte aos outros.",
"3jm":"<b>Membro do LAG adicionado.</b><br>{net} em {city} agora é {lag}.",
"3jn":"<b>Membro do LAG removido.</b>",
"3jo":"<b>Transit da {net} ativo em {city}.</b><br>Full table recebida: ~1.000.000 de rotas.",
"3jp":"<b>Sem transit neste cenário.</b><br>Só peering, PNIs, caches e sua própria fibra.",
"3jq":"<b>Você cancelou {name}.</b><br>Foram quatro cliques, uma pesquisa e uma página de “que pena que você vai embora”.",
"3jr":"<b>Porta ativa no {ix}!</b><br>Agora peça peering ou entre no route server.",
"3js":"<b>Porta remota ativa no {ix}.</b><br>Veio por um revendedor, então espere uma margem extra, uma porta lotada e algumas redes que não vão falar com você. Aqui o route server é seu amigo.",
"3jt":"<b>Sessão com o route server ativa.</b><br>Agora você faz peering com todas as redes abertas deste IX, de uma vez só.",
"3ju":"<b>Roteador instalado em {city}.</b><br>O fornecedor mandou do lado certo, então os técnicos locais viraram. Aqui tudo é de cabeça para baixo.",
"3jv":"<b>Roteador instalado em {city}.</b><br>De cabeça para baixo, como é costume por aqui. Os pacotes não parecem se importar.",
"3jw":"<b>Contrato assinado com a DE-KICKS.</b><br>Bem-vindo à família. Por favor, não conte a ninguém quanto você paga.",
"3jx":"Ficar com o desconto",
"3jy":"<b>Este PNI já agrupa {n} portas</b>, tudo o que os teus routers aqui aguentam. Cada router aguenta {more} membros de um PNI, até {max}: adiciona um router para mais.",
"3jz":"Espere! Antes de ir…",
"3k":"Participe de uma conferência.",
"3k0":"Valorizamos demais nossa parceria para deixar uma bobagem como o preço atrapalhar.",
"3k1":"<b>Primeiro você precisa de uma licença.</b><br>Redes estrangeiras precisam de uma joint venture para construir na China continental.",
"3k2":"Uma fibra aqui usa ópticas que este modelo não aceita.",
"3k3":"Tem uma porta aqui maior que {pn}.",
"3k4":"Tem uma wave aqui mais rápida que {pn}.",
"3k5":"<b>Nenhuma porta de router livre em {city}.</b><br>{u} de {m} em uso. Adicione um router ou troque por um modelo com mais portas (aba Infra).",
"3k6":"Você usa {u} portas aqui e {r} × {model} só tem {max}.",
"3k7":"Endereços IP, localizações mais precisas do que um país, nem o teu aparelho, navegador ou fuso horário. Um servidor usa o endereço da tua ligação só em memória, para saber o país e travar inundações, e nunca o escreve. Os servidores registados prometem que nada à frente deles regista endereços também.",
"3k8":"<b>Sai</b> de um servidor e o teu jogo deixa de falar com ele; o que ele guardava desvanece em 180 dias. <b>Sair de vez</b> assina uma despedida que pede a cada servidor para apagar já os registos da tua rede (só a despedida fica, 180 dias, para se espalhar), e este jogo guardado esquece a sua identidade Multimode. Apagar um jogo guardado tira-o deste aparelho.",
"3k9":"Sair",
"3ka":"Sem conta, sem email, sem cookies. Aqui está tudo o que o jogo guarda e tudo o que sai do teu aparelho.",
"3kb":"Em seriesoftub.es a página carrega um pequeno contador de visitas (do jsDelivr, que reporta a stats.seriesoftub.es). Conta uma visita com o endereço da página, a página de onde vens e a largura da janela, quanto tempo a página ficou aberta e os nomes de alguns momentos do jogo, como começar um jogo novo ou ganhar um distintivo. Não usa cookies nem guarda nada no teu navegador. O contador é o ridiculytics, feito pelo autor do jogo e alojado no nosso próprio servidor: sem base de dados, nada escrito em disco, só contagens em memória (por página, site de onde vens como nome de anfitrião, país, navegador, sistema operativo, tipo de dispositivo, classe de tamanho de ecrã e momento do jogo). O teu endereço IP só é usado enquanto a visita é contada, para saber o país, e nunca é guardado nem registado; os visitantes únicos são contados com um hash cujo segredo muda a cada 24 horas, por isso as visitas não podem ser ligadas entre dias. Cópias do jogo noutros sítios não enviam nada.",
"3kc":"Neste aparelho",
"3kd":"Esta página na web",
"3ke":"O contador de visitas",
"3kf":"Os números de tráfego durante 72 horas (e os teus mais recentes), os acordos 30 dias e a descrição da tua rede até ficar 180 dias calada. As horas são arredondadas a cinco minutos. Os votos dos operadores sobre uma rede duram 97 dias.",
"3kg":"O que os servidores guardam",
"3kh":"O que os servidores nunca guardam",
"3ki":"O que o jogo guarda",
"3kj":"O que o jogo guarda e envia",
"3kk":"Quando entras num servidor",
"3kl":"Enquanto jogas",
"3km":"Os teus números atuais (os mesmos de cima, nada mais) a cada 10 segundos enquanto o jogo está aberto e mudaram, para que as classificações mostrem o que acontece agora. Os servidores guardam-nos só em memória, nunca em disco, e esquecem-nos 15 minutos depois dos últimos.",
"3kn":"O teu jogo envia estes registos assinados: o nome, número AS e mercado de origem da tua rede no jogo, o dia de jogo e o dia real em que entrou, as suas cidades com POP e exchange, número de clientes, números e mistura de tráfego, quanto tráfego troca com a rede de cada outro jogador, se é Tier 1 ou Tier 2, a política e os preços publicados, a quem compra ou vende trânsito (nunca o preço), e o modelo e o harness de IA quando um agente de IA a joga. Os acordos vão selados só para o outro jogador. Uma denúncia que envies sobre outra rede (que rede, e porquê) vai para os operadores desse servidor. O teu país real é acrescentado enquanto <b>Partilhar o meu país</b> estiver ligado, e está ligado até o desligares.",
"3ko":"Os teus jogos guardados, configurações, medalhas e progresso ficam no armazenamento deste navegador. No Multimode junta-se a chave privada da tua rede (dentro do jogo guardado), o que os teus servidores enviaram sobre outras redes (esquecido após 180 dias sem notícias) e uma chave de operador, se importaste uma. Nada é enviado a não ser que entres num servidor ou envies tu um jogo guardado.",
