"3r0":"Um exchange comunitário num porão da Hudson Street. Schmear não incluso.",
"3r1":"Um exchange comunitário que funciona em cima de um bar de sidra. Minúsculo, barato, e todo membro ganha um copo.",
"3r2":"Um exchange comercial menor, na mesma rua do DE-KICKS. Publica seus preços numa página da web, o que o DE-KICKS considera um ato de guerra. As portas vêm sem webinar de vendas.",
