"3rd":"Abre às seis, vem com petiscos grátis e fecha quando cai a última sessão.",
"3re":"Gerido por hackers à base de cafeína. O route server tem globo de discoteca.",
"3rf":"Peering settlement-free com raízes frísias. As portas 10G e 100G não custam nada. Traga um ASN e apetite por route servers. Maionese é à parte.",
"3rg":"Nasceu na garagem de alguém, como tudo por aqui.",
"3rh":"Forte, docinho e mais barato que o incumbente.",
"3ri":"Leva uma eternidade pra configurar, mas enche a barriga.",
"3rj":"O desafiante. Fresquinho toda manhã, meio amanhecido à noite.",
"3rk":"A desafiante do IX Straya. Aparece na borda de toda cidade, inclusive nas que ninguém mais se dá ao trabalho de atender. Um gosto adquirido, como Vegemite.",
"3rl":"O desafiante do fabric DE-KICKS, embrulhado e pronto pra viagem.",
"3rm":"O tradicional exchange de Madrid. Interconexão neutra, sabor local e um route server que nunca tira siesta.",
"3rn":"O exchange mais antigo de Johannesburg, gerido pela associação de ISPs locais. Bata na madeira antes de cada janela de manutenção.",
"3ro":"O bairro inteiro carrega a casa junto. Entrar é grátis, com a bênção do governo.",
