"3tp":". Você quis dizer {name}?",
"3tq":"Durante um ataque, coloque o alvo em blackhole no upstream (RTBH). Todo mundo é salvo; o alvo fica fora do ar até você remover a regra.",
"3tr":"Todo gigabit que sai da sua rede escolhe uma saída: uma PNI, uma porta de IX ou uma porta de trânsito. Por conta própria, ele pega o peering mais próximo que tem espaço (na mesma cidade, a PNI antes da porta de IX), e trânsito só quando nenhum peering consegue levar. O RouteScript muda essas escolhas, como local-pref, AS-path prepending e drains de manutenção fazem em roteadores de verdade.",
"3ts":"Preenchidos a partir da sua rede como ela está agora. Carregue um, leia, verifique e depois faça o deploy.",
"3tt":"Um degrau de spill: quando o caminho mais curto está assim cheio, o excesso segue o melhor desvio se não acrescentar mais do que esses milissegundos e ficar abaixo da mesma linha. Empilha-os (80% within 10 ms, 90% within 20 ms) para desviar mais cedo e mais longe à medida que os links aquecem.",
