"3yq":"Alcance 50% da internet e atenda 300 Gbps",
"3yr":"Crise no Mar Vermelho",
"3ys":"Rio do zero. O Carnaval começa em 90 dias e quer 400 Gbps por cinco dias seguidos. O mundo inteiro está assistindo.",
"3yt":"<b>Modo sandbox</b><br>Um bilhão de dólares e tudo desbloqueado. Caos: {chaos}. Construa a internet que você sempre quis, e deixe uma retroescavadeira reserva à mão.",
"3yu":"<b>Modo sandbox</b><br>Um bilhão de dólares, tudo desbloqueado e nada nunca quebra. Construa a internet que você sempre quis.",
"3yv":"São Paulo. O Brasil é um continente: quarenta exchanges IX.brrr, milhares de provedores e a Amazônia entre você e o norte.",
"3yw":"Seul, onde quem envia paga. Cada Gbps que um carrier entrega na Coreia custa uma taxa de «quem envia paga» além da conta de trânsito, os três incumbentes só conversam por um PNI pago, o gigabit residencial sai pelo preço de um bibimbap e os usuários coreanos percebem cada milissegundo. O trânsito em Tóquio é barato, se seus clientes aguentarem a viagem.",
"3yx":"{g} Gbps servidos, Seul bem servida ({q}%), 99% de alcance e lucro mensal",
"3yy":"Temporada de tubarão: cortes submarinos duas vezes mais prováveis",
"3yz":"Comece em Panama City. Nada atravessa o Darién Gap por terra, e os Andes atrapalham todo o resto.",
"3z":"Publique um RouteScript que derrube um terço do seu tráfego.",
"3z0":"Comece em Stuttgart, onde ninguém vende transit. Alcance a internet só com peering, PNIs, caches e sua própria fibra. Nada de transit, em lugar nenhum, nunca.",
"3z1":"Comece com só $100k",
"3z2":"Sydney, 2013. O Toilet Paper Group levou a própria fibra até o porão dos prédios, e a rede nacional reclamou de cherry-picking. Sua vez: pule a Nearly Broadband Network, pague a taxa e chegue primeiro.",
"3z3":"Tallinn, onde ninguém vende trânsito: a sua internet fica do outro lado do mar. Os navios arrastam âncoras sobre os cabos do Báltico três vezes mais que o normal.",
"3z4":"A briga da Cogentle",
"3z5":"Transit custa 30% a mais",
"3z6":"O dobro de falhas",
"3z7":"Semanal {key}",
"3z8":"<b>Boas-vindas, {name}!</b><br>O RIPE NCC te atribuiu o AS{asn}. Seu primeiro router já está zumbindo em {city}.",
"3z9":"Você tem {n} dias.",
"3za":"<b>Pedido protocolado.</b><br>Seu parceiro local diz uns 45 dias. Provavelmente.",
"3zb":"<b>Add-on clean-pipe ativado em {net}.</b><br>Eles limpam um flood antes de chegar na sua porta aqui, por {mo}/mês.",
"3zc":"<b>Add-on clean-pipe removido de {net}.</b>",
"3zd":"<b>O HackBack 3000™ acertou o alvo errado.</b><br>{who} Um órgão regulador te manda uma multa de {fine}, e o ataque continua.",
"3ze":"<b>O HackBack 3000™ contra-ataca!</b><br>A Skynot AI rastreou a botnet e educadamente a transformou em tijolo. O ataque a {city} para na hora.",
"3zf":"<b>O PNI com {net} voltou ao normal.</b>",
"3zg":"<b>O PNI com {net} agora é um gargalo de sacrifício.</b><br>Um flood vindo de lá morre na porta pequena em vez de dentro da sua rede, mas o tráfego legítimo passa com metade da capacidade.",
"3zh":"<b>Nenhum ataque para mandar ao blackhole agora.</b>",
