"3zk":"A Skynot AI derrubou a geladeira conectada de uma vovó.",
"3zl":"A botnet já era a botnet de outra pessoa. Eles estão furiosos.",
"3zm":"<b>Centro de scrubbing {tier} no ar em {city}.</b><br>Ataques de até {g} são limpos, e você pode vender proteção DDoS.",
