"failures.somebody_who_did_not_like_your":"alguém que não gostou do nome da sua rede",
"failures.someone_filtered_all_icmp_on_your":"Alguém filtrou todo ICMP na sua borda “por segurança”. O Path MTU discovery quebrou, e as conexões com {net} travam logo depois do handshake.",
