"failures.the_monsoon_flooded_a_manhole_on":"A monção alagou uma caixa subterrânea em {a}–{b}. A fibra agora está debaixo d’água, assim como a caixa.",
"failures.the_repair_ship_s_compass_spun":"A bússola do navio de reparo girou em círculos sobre o seu cabo {a}–{b}. Ele está rompido, e ninguém concorda onde.",
