"failures.thieves_dug_up_your_a_b":"Ladrões desenterraram seu cabo {a}–{b}, certos de que era cobre. Era fibra. Deixaram tudo cortado na vala, profundamente decepcionados.",
"failures.your_a_b_cable_broke_in":"Seu cabo {a}–{b} quebrou no mesmo ponto da última vez. A equipe de reparo reconheceu.",
