"ops.o_caches":"Aceitar caches grátis",
"ops.o_caches_d":"Instalar cada cache grátis que uma rede oferece, assim que o tráfego dela na cidade passar de um limite.",
"ops.o_decom":"Desativar links paralelos pequenos",
"ops.o_decom_d":"Quando um link maior entre duas cidades estiver no ar, devolver as waves menores que não fazem mais falta. Nunca uma que um cliente aluga ou de que depende.",
"ops.o_fabric":"Ampliar os seus exchanges",
"ops.o_fabric_d":"Melhorar o fabric de um exchange seu quando o tráfego passa a folga, ou quando não há mais vagas e uma rede espera para entrar. Um fabric maior leva mais tráfego e aceita mais membros pagantes.",
"ops.o_ix":"Peering em cada IX",
"ops.o_ix_d":"Toda semana: entrar nos route servers e pedir peering a cada membro disposto em cada uma das suas portas de exchange.",
"ops.o_optics":"Acender mais fibra",
"ops.o_optics_d":"Adicionar ópticas à fibra escura que está esquentando e acender a fibra nova no dia da entrega.",
"ops.o_optup":"Melhorar o transporte óptico",
"ops.o_optup_d":"Na fibra que está cheia e esquentando, ou da qual os compradores do mercado de capacidade querem mais do que ela pode vender, sobe o sistema de linha um tamanho ou troca os canais menores por ópticas maiores (as antigas vão para a prateleira). Escolha um sistema de linha e cada fibra com um menor sobe para ele. Trocar o sistema de linha derruba a fibra por um dia, então só onde o tráfego consegue contorná-la e nenhum cliente passa por ela, uma por noite.",
"ops.o_pie":"Manter as crostas cheias",
"ops.o_pie_d":"Reserva lançamentos para que as suas crostas continuem cheias à medida que as tortas velhas se desgastam: tortas do stock da fábrica, a primeira plataforma livre, nunca um voo de teste. Cada um custa o que o separador Crostas cobra.",
"ops.o_pni":"PNI com os grandes",
"ops.o_pni_d":"Toda semana: pedir um PNI com cada rede disposta que mande tráfego suficiente nos seus POPs, no tamanho mínimo de cada rede.",
"ops.o_ports":"Folga nas portas de peering",
"ops.o_ports_d":"Manter as portas PNI e IX acima de um múltiplo do tráfego de hoje: uma porta única num POP com vários roteadores ganha uma segunda em LAG, todas as outras sobem um tamanho de porta.",
"ops.o_repair":"Acelerar reparos",
"ops.o_repair_d":"Pagar o reparo urgente de cada queda que tenha um, enquanto o orçamento durar.",
"ops.o_routers":"Roteadores à frente",
"ops.o_routers_desc":"Adicionar um roteador, ou trocar para a próxima geração onde um segundo roteador segura o tráfego, quando a carga ou as portas passarem de um nível. Escolha um modelo e cada POP com um menor é trocado para ele, o mais carregado primeiro, dentro do orçamento.",
"ops.o_transit":"Folga de trânsito",
"ops.o_transit_d":"Manter o trânsito de cada POP acima de um múltiplo do seu pico de 30 dias: mais um membro LAG, ou um tamanho de porta acima.",
"ops.o_waveup":"Waves alugadas maiores",
"ops.o_waveup_d":"Subir uma wave alugada um tamanho quando está no limite, a não ser que nessa rota passe ou esteja sendo construída fibra escura sua.",
