"oq":"Tango, carne e uma turma muito fiel de provedores locais.",
"or":"A maior cidade da Tanzânia e a porta para o mar de meia dúzia de países sem litoral.",
"os":"O primeiro cabo de Tarawa chegou em 2026: dois mil quilômetros até Nauru e Pohnpei, pagos por três governos amigos.",
"ot":"A capital da pesca das Aleutas. A fibra chegou em 2023; antes disso, satélites e paciência.",
"ou":"Os Açores, no meio do Atlântico. Os cabos da Flórida para Lisboa e para a Espanha param aqui, então um POP divide a travessia e cada metade leva mais. Há mais vacas do que servidores.",
"ov":"A capital das Bahamas, a um pulinho da Flórida. A maioria dos cabos rumo ao sul para aqui no caminho.",
"ow":"A maior cidade ao norte do Círculo Polar Ártico. O cabo russo Polar Express deveria partir daqui rumo ao leste; só o primeiro trecho está na água. Lance o seu.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Uma frota pesqueira está arrastando redes bem onde você precisa lançar.",
"own_cable.a_whale_has_parked_on_the":"Uma baleia estacionou na rota e não quer sair.",
"own_cable.storm_season_the_ship_is_sheltering":"Temporada de tempestades. O navio está abrigado no porto, jogando baralho.",
"own_cable.the_cable_ship_s_coffee_machine":"A máquina de café do navio lançador quebrou. Ninguém trabalha sem café.",
"own_cable.the_crew_fished_out_somebody_else":"A tripulação pescou o cabo de outra pessoa por engano e precisa devolvê-lo.",
"own_cable.the_seabed_survey_found_an_old":"O levantamento do leito marinho achou uma mina antiga. Um desvio pequeno e muito cuidadoso.",
"ox":"O fim do país, em linhas de energia construídas para uma fundição de alumínio. Alguém está construindo um campus de IA de 280 MW num pasto fora da cidade, então os cabos vão chegar. Provavelmente.",
"oy":"O pé do mapa. Ar fresco, energia hidrelétrica barata e o Estreito de Bass inteiro entre você e o continente.",
"oz":"A capital dos negócios da África Ocidental francófona, com torres de vidro numa laguna e cinco cabos na baía.",
"p":"{city} fica no escuro",
"p0":"As Canárias, a um pulo de Lisboa e do Marrocos. Quase todo cabo que desce a costa oeste da África para aqui, e o longo trecho até Lagos vira dois mais curtos.",
"p1":"A capital, construindo campi de IA em escala de gigawatt. Dados de usuários sauditas precisam ficar no Reino, e todo POP precisa de licença de telecom local.",
"p2":"A capital fica aqui; a internet, a trinta quilômetros, em Cotonou, onde os cabos chegam e o exchange funciona.",
"p3":"A capital do Acre, o estado que os brasileiros brincam que não existe. Seus traceroutes dizem o contrário.",
"p4":"A capital das Ilhas Marshall, um anel de coral a dois metros acima do mar. Um único cabo para Guam, e todo pacote sabe disso.",
"p5":"O exchange da capital é pequeno: o movimentado de Honduras fica em San Pedro Sula, a cidade das fábricas no norte.",
"p6":"A capital. Dinheiro soberano para IA e data centers enormes. Nos Emirados, só as duas operadoras licenciadas podem passar fibra.",
"p7":"A capital escreve as regras com que a internet funciona e deixa os servidores ao lado: os data centers ficam a meia hora, em Ashburn, então a cidade em si é um mercado pequeno com usuários muito importantes.",
"p8":"O Cáspio não tem saída para o oceano, então o tráfego de Baku sai por terra, principalmente para oeste pela Geórgia.",
"p9":"A cidade da eterna primavera, com escadas rolantes a céu aberto subindo os morros e uma cena de startups agitada.",
"pa":"A capital dos data centers. Dizem que 70% da internet passa por aqui, e ninguém conferiu.",
"pb":"O extremo sul, a meio caminho de Buenos Aires. Churrasco todo domingo e uma cuia de chimarrão em cada mão, até no verão.",
"pc":"A capital da República Dominicana, a cidade europeia mais antiga das Américas e um ponto de chegada de cabos bem movimentado.",
"pd":"A cidade mais a leste das Américas, onde o sol nasce primeiro. Seu plantão no NOC começa cedo também.",
"pe":"O fim da Transiberiana, e do cabo da Rússia para o Japão.",
"peering_desk.closed_desc":"Todo pedido de peering é recusado, e sem route servers. Os clientes ficam sabendo que você é difícil de alcançar, então menos deles ligam.",
