"pv":"A única capital nordestina longe do mar. Famosa pelo calor, com tempestades de raios que mantêm os protetores de surto ocupados.",
"pw":"A porta para o Pacífico. Os Andes ficam entre ela e todo o resto, e de vez em quando a terra treme.",
"px":"A segunda cidade das Filipinas, alcançada só por cabo nacional. Os tufões passam por aqui a caminho do norte.",
"py":"A porta das pradarias entre Vancouver e o resto do Canadá. Um chinook derrete a neve numa tarde, e aí neva de novo.",
"pz":"O hub do Reno-Ruhr: mais data centers neutros do que Hamburgo ou Munique, e a uma hora da fronteira holandesa, então a fibra até Amsterdã é curta e barata. Aqui se pede uma Altbier, nunca uma Kölsch.",
"q":"Faltam {g} em {city}",
"q0":"A capital das Seychelles, em Mahé: 115 ilhas, tartarugas gigantes e dois cabos para o continente.",
"q1":"A capital das Ilhas Salomão, em Guadalcanal. O cabo para Sydney só chegou há poucos anos; antes era tudo satélite. A energia é menos confiável que o cabo.",
"q2":"O carrier hotel do Sudeste. Aeroporto mais movimentado, peering mais movimentado ao sul de Ashburn.",
"q3":"É aqui, na costa basca, que chegam os cabos transatlânticos. O exchange fica em Madrid, então quase todo o tráfego segue para o interior.",
"q4":"A Veneza brasileira, toda pontes e rios, com um dos maiores parques tecnológicos do país no porto antigo.",
"q5":"O país inteiro é uma só rede anunciando um punhado de rotas, e as casas comuns não estão nela.",
"q6":"O país inteiro em um cabo: um ramal do ACE, que chegou em 2011 e é compartilhado por todas as operadoras.",
"q7":"A capital do Yukon, numa única e longa fibra pela Alaska Highway: um corte ao sul da cidade e o território inteiro espera.",
"q8":"Faz o maior São João do mundo: um mês inteiro de forró todo junho. E é cidade universitária, cheia de engenheiros.",
"q9":"O primeiro cabo do Timor-Leste foi ligado em julho de 2026: seiscentos quilômetros até o North-West Cable System da Austrália.",
"qa":"Pequena, tropical e a cidade australiana mais perto da Ásia. Cabos novos para Singapura e Jakarta chegam aqui, ao lado dos crocodilos.",
"qb":"Tonga depende de um único cabo vindo de Fiji. Em 2022 um vulcão submarino o cortou, e o país ficou offline por semanas.",
"qc":"A capital de Trinidad, na ponta sul da cadeia de ilhas e a poucos quilômetros da Venezuela.",
"qd":"Doze mil pessoas e o primeiro cabo delas, que chegou em agosto de 2025 a caminho de Tarawa para Pohnpei.",
"qe":"A vinte minutos de tudo, menos de qualquer outro lugar.",
"qf":"Cidades gêmeas, um exchange e passarelas entre os prédios: Minneapolis também faz peering aqui, e em janeiro ninguém sai para emendar uma fibra.",
"qg":"Dois milhões de pessoas no meio da floresta, com uma zona franca de fábricas. A fibra segue os rios e, quando rompe, a equipe de reparo vai de barco.",
"qh":"Dois exchanges rivais, um na universidade técnica e outro comercial, e a maioria das redes eslovacas está nos dois.",
"qi":"Tufões, terremotos e muita gente cronicamente online.",
"qj":"Os engenheiros de rede ucranianos mantiveram a internet de pé em meio a apagões e coisa muito pior. Geradores, fibra reserva e redundância em tudo são padrão aqui, e a cena de peering é famosa por ser casca-grossa.",
"qk":"Universidades, biotech e um carrier hotel que sobreviveu à maioria dos seus carriers.",
"ql":"Uruguai: fibra em quase toda casa, um notebook para cada aluno e uma telco estatal que cuida de quase tudo.",
"qm":"Cronicamente online e mal servida pelo mar: a qualquer momento, pelo menos um dos seus cabos submarinos está rompido.",
"qn":"A capital da Virgínia, onde os cabos transatlânticos de Virginia Beach chegam ao interior até um exchange neutro: um caminho mais tranquilo para a Europa do que Ashburn.",
"qo":"O calor residual vai direto para o spa ao lado.",
"qp":"Quando seu único cabo foi cortado em 2018, a Mauritânia ficou quase totalmente offline por dois dias.",
"qq":"Quando o cabo chegou em 2025, o país inteiro ganhou internet grátis por um dia para comemorar.",
"qr":"Onde Brasil, Argentina e Paraguai se encontram, ao lado de cataratas gigantes e de uma usina ainda maior. A energia é barata, a papelada da alfândega não.",
"qs":"Onde os cabos da África Oriental chegam à terra e depois sobem de trem até Nairóbi.",
"qt":"Onde os cabos da América do Sul chegam de verdade. Europa, África e EUA desembarcam aqui e depois pegam um longo backhaul para o sul.",
"qu":"Onde chegam os cabos atlânticos do sul da África. Pinguins na praia, apagões programados na rede elétrica.",
"qv":"Casas brancas subindo a partir do Mediterrâneo. Os cabos vão para o norte, até Marselha, e boa parte do tráfego também.",
"qw":"Conectada por quatro caminhos para menos de um milhão de pessoas: EASSy, 2Africa e dois cabos curtos até Mayotte.",
"qx":"A Zâmbia vive da energia de um grande lago. Num ano seco o lago baixa, e a rede elétrica também.",
"qy":"100G por caixa",
