"routescript.business_customers_first_when_links":"Clientes empresariais primeiro quando os links estão congestionados, e um spill mais cedo para que isso quase nunca aconteça.",
"routescript.cheapest_upstream_first_priciest":"O upstream mais barato primeiro, o mais caro por último, e o tráfego muda antes que as portas encham. Corta a conta de trânsito sem derrubar ninguém.",
"routescript.done_i_vibe_checked_your_bgp":"Pronto! Fiz um vibe check no seu BGP. Faça o deploy agora mesmo: dry run é para quem duvida de si.",
"routescript.drain_a_pop_and_steer_around":"Esvazie um POP e desvie de um dos links dele antes de mexer. Troque os nomes pelos que você vai mexer.",
"routescript.for_a_ddos_rtbh_the_target":"Para um DDoS: coloque o alvo em blackhole no upstream e priorize os clientes empresariais. O alvo fica fora do ar enquanto durar, então remova quando o ataque acabar.",
"routescript.great_question_here_is_a_production":"Ótima pergunta! Aqui está um script pronto para produção, sob medida para o seu tráfego. Eu verifiquei tudo com cuidado.",
