"sales.auto_ceo":"{name} assina as ofertas que sua rede consegue atender hoje, um teste por dia. Ele também recusa as que ficam abaixo do seu mínimo, mas de vez em quando já apertou a mão.",
"sales.auto_eng":"{name} assina as ofertas que sua rede consegue atender hoje, depois de testar cada uma na rede (uma por dia), e recusa as que pagam menos que o seu mínimo.",
"sales.auto_shark":"{name} assina toda oferta assim que ela chega, com promessas e tudo, desde que você possa pagar a comissão, e recusa as que pagam menos que o seu mínimo.",
"sales.ceo_d":"De graça, e convicto. A cada dois meses fecha um contrato enorme no campo de golfe com 30% de desconto, muitas vezes com uma promessa que ninguém conferiu, e de vez em quando assina uma oferta que você recusou. Tem opiniões. Não pode ser demitido.",
