"sales.ceo_say_blockchain":"Já pensamos em colocar a tabela de rotas numa blockchain?",
"sales.ceo_say_golf":"Os melhores negócios saem no nono buraco. O NOC devia jogar mais golfe.",
"sales.ceo_say_mbps":"Por que vendemos gigabits? Megabits parecem mais.",
"sales.ceo_say_napkin":"Fiz o preço do próximo contrato num guardanapo. A engenharia resolve os detalhes.",
"sales.ceo_say_synergy":"Não vendemos banda, vendemos sinergia. Coloquem isso no site.",
"sales.ceo_sky":"Em órbita: metade das partidas de golfe é com o Fundador, pelo maior contrato em órbita que couber, com 30% de desconto. Mercados nervosos custam caro: preços menores em órbita, e nada de golfe quando estão muito nervosos.",
"sales.eng_d":"Era engenheiro de redes e agora tem o crachá de cada NOG. Inscreve você em todas (o ingresso é por sua conta), traz muitos negócios pequenos e médios, mas nunca os realmente grandes, e só vende o que a rede consegue entregar, então os clientes ficam. Os nerds adoram o Dave. Negocia mal.",
"sales.eng_n":"O engenheiro que virou vendedroide",
"sales.eng_s":"Dave",
"sales.eng_sky":"Em órbita: só vende onde a antena de pouso tem folga, e esses clientes ficam como os nerds.",
"sales.ren_ceo":"{name} responde à renegociação de um cliente três dias depois de começar, no campo de golfe: mais desconto do que pediram em troca de um contrato com o dobro da duração, um sim rápido, ou uma briga que termina com o cliente indo embora.",
"sales.ren_ceo_fight":"{name} disse a {cust} que ninguém pechincha com ele. Foram embora.",
"sales.ren_ceo_yes":"{name} disse sim a {cust} antes que alguém pudesse conferir: {price}/mês.",
"sales.ren_eng":"{name} responde à renegociação de um cliente três dias depois de começar. Clientes nerds ganham uma tarde com os diagramas da rede e quase sempre renovam a preço de mercado; os outros recebem o desconto que pediram. Ninguém sai.",
"sales.ren_eng_cave":"{name} deu a {cust} o desconto que pediram: {price}/mês. Eles ficam.",
"sales.ren_eng_tech":"{name} passou uma tarde mostrando a rede aos engenheiros da {cust}. Renovam a {price}/mês, sem desconto.",
"sales.ren_mid":"{name} e {cust} chegaram a um meio-termo: {price}/mês.",
"sales.ren_shark":"{name} responde à renegociação de um cliente três dias depois de começar, e não cede nada: a maioria renova ao preço antigo, muitas vezes com uma nova promessa, e ele te cobra um mês do que economizou. Alguns vão embora, principalmente os nerds.",
"sales.ren_shark_walk":"{name} jogou duro com {cust}, e eles foram embora.",
"sales.shark_d":"Fecha os maiores negócios por um quarto a mais, e leva um mês de cada contrato de comissão. Vende demais: metade chega com uma promessa que sua rede ainda não cumpre, e esses clientes saem mais cedo. Ignora os nerds: nada de clientes técnicos nem de encontros, e as equipes de peering pedem um quarto a mais de tráfego. Ganha quase todas as negociações.",
"sales.shark_n":"O tubarão",
"sales.shark_s":"Chad",
"sales.shark_sky":"Em órbita: liga primeiro para companhias aéreas e cruzeiros, no maior tamanho e por um quarto a mais, e promete a metade deles um céu cheio antes de você ter um. Eles reclamam até você ter.",
