"specialist.cable_broker":"Corretor de cabos",
"specialist.cable_broker_desc":"Lance fibra em terra e cabos sob o mar desde o primeiro dia, acenda-os e venda a capacidade a outras operadoras. Metas próprias; vença como Barão do Vidro: seus próprios cabos chegam a {n} continentes enquanto as operadoras pagam {m} por mês. Todo o resto desbloqueia por nível, como sempre.",
"specialist.global_backbone":"Backbone global",
"specialist.low_latency_boutique":"Boutique de baixa latência",
"specialist.spotted_your_broadband_in_a_one":"Eles viram sua banda larga em {a}, uma das grandes cidades de usuários.",
"specialist.spotted_your_cap_of_dark_fiber":"Eles viram seus {cap} de dark fiber acesa entre {a} e {b}.",
"specialist.spotted_your_ms_ms_a_b_path":"Eles viram seu caminho {a}–{b} de {ms} ms.",
"specialist.spotted_your_two_diverse_paths_a":"Eles viram seus dois caminhos diversos entre {a} e {b}.",
"specialist.the_classic_game_grow_everywhere_and":"O jogo clássico: cresça em todo lugar, os clientes seguem seu nível e Tier 1 é a vitória.",
"specialist.trading_firms_and_other_latency_customers":"Firmas de trading e outros clientes de latência ligam mais vezes e pagam {p}% a mais. Vença Velocidade da luz: supere a latência alugada mais rápida em {r} rotas financeiras com sua própria fibra enquanto {c} clientes de latência pagam você. Tier 1 continua valendo.",
"sq":"Ainda não tem IX aqui. Você pode fundar um depois.",
"sr":"Ninguém vende transit aqui. Leve seu tráfego por fibra até uma cidade que tenha.",
"ss":"Nada plugado aqui ainda",
