"su":"Um router só é um single point of failure.",
"supply_chain.chip_shortage_every_router_vendor_is":"<b>Falta de chips!</b><br>Todo fabricante de roteador está esperando os mesmos chips. Roteadores novos e upgrades custam 40% a mais por {n} dias. Prazo de entrega: “sim”.",
"supply_chain.every_cable_ship_is_booked":"<b>Todos os navios lançadores de cabo estão reservados.</b><br>Os hyperscalers contrataram todos os navios e todas as equipes de escavação do planeta. Novas fibras e novos cabos custam 30% a mais por {n} dias.",
"supply_chain.laser_shortage_the_factory_that":"<b>Falta de lasers!</b><br>A fábrica que faz os lasers de metade das ópticas do mundo inundou. Ópticas custam 50% a mais por {n} dias. Os sobressalentes na sua prateleira acabaram de virar o melhor investimento da sua vida.",
"supply_chain.new_fiber_and_cable_builds":"Novas fibras e novos cabos",
