"t8":"Quando ligado, ele anuncia o alvo de forma mais específica, então as enxurradas chegam na entrada de {g} dele em vez das suas portas, e ele limpa tudo. O tráfego limpo volta pelo seu backbone. Ele também libera contratos de proteção DDoS.",
